const editorial={
es:{line:'Guitarras de autor',intro:'Tradición, búsqueda sonora y una relación personal con cada músico.',collection:'Una voz, una compañera.',evolution:'En constante evolución…',photo:'Fotografías reales del taller. La correspondencia con cada modelo está pendiente de confirmar.',craft:'El oficio de escuchar.',craftText:'Soy Víctor Iermito, luthier de guitarras clásicas en Francia. Mi trabajo une la tradición de la guitarra española con una búsqueda sonora en constante evolución. Cada conversación con un músico abre nuevas posibilidades.',discover:'Descubrir',listen:'Escuchar',enquire:'Conversar sobre este instrumento',essence:'La tradición como punto de partida.<br>El sonido como horizonte.',soundText:'Proyección, riqueza y respuesta al tocar. Una búsqueda que se renueva en cada instrumento.',detail:'La precisión se descubre de cerca.',real:'VICTOR IERMITO · FOTOGRAFÍA ORIGINAL',models:{'T-1':['La sencillez esencial.','La propuesta más sencilla de la familia T. Una guitarra de estética sobria, construida con el mismo cuidado artesanal.',['Estética sencilla']],'T-2':['Sonido y equilibrio.','Para quienes valoran un buen sonido, la comodidad al tocar y una estética sobria. Una guitarra para disfrutar de la música, con el cuidado artesanal presente en cada detalle.',['Buen sonido','Confort de toque','Estética sobria']],'T-3':['Tradición en evolución.','Para guitarristas experimentados que buscan mayor proyección, riqueza de armónicos y un sustain más prolongado, sin resignar la comodidad al tocar ni la calidez y la dulzura de la guitarra clásica española.',['Comodidad al tocar','Mayor proyección','Riqueza de armónicos','Sustain prolongado','Calidez y dulzura tradicionales']],ECO:['Otras maderas. Nuevas voces.','Una línea nacida de la investigación de maderas alternativas. Mis raíces y el oficio adquirido en Francia se encuentran en una exploración de materiales, combinaciones y posibilidades sonoras, con respeto por el medioambiente.',['Investigación de materiales','Raíces argentinas','Exploración sonora']],special:['Otras formas de hacer música.','Guitarrón argentino, guitarra bajo y requinto. Instrumentos vinculados a las músicas de Latinoamérica, cada uno con su registro, su función y su propia identidad.',['Guitarrón argentino','Guitarra bajo','Requinto']],custom:['Un proyecto que empieza contigo.','El punto de partida es una conversación: tu manera de tocar, el sonido que buscas y tus preferencias. Juntos definiremos las posibilidades del instrumento y los detalles de un proyecto personal.',['Escucha y diálogo','Búsqueda compartida','Detalles personales']] }},
fr:{line:'Guitares d’auteur',intro:'Tradition, recherche sonore et relation personnelle avec chaque musicien.',collection:'Une voix, une compagne.',evolution:'En constante évolution…',photo:'Photographies originales de l’atelier. Leur correspondance avec chaque modèle reste à confirmer.',craft:'L’art d’écouter.',craftText:'Je suis Victor Iermito, luthier de guitares classiques en France. Mon travail associe la tradition de la guitare espagnole à une recherche sonore en constante évolution. Chaque échange avec un musicien ouvre de nouvelles possibilités.',discover:'Découvrir',listen:'Écouter',enquire:'Parlons de cet instrument',essence:'La tradition comme point de départ.<br>Le son comme horizon.',soundText:'Projection, richesse et réponse sous les doigts. Une recherche qui se renouvelle avec chaque instrument.',detail:'La précision se révèle de près.',real:'VICTOR IERMITO · PHOTOGRAPHIE ORIGINALE',models:{'T-1':['La simplicité essentielle.','La proposition la plus simple de la famille T. Une guitare à l’esthétique sobre, construite avec le même soin artisanal.',['Esthétique simple']],'T-2':['Son et équilibre.','Pour ceux qui apprécient un beau son, le confort de jeu et une esthétique sobre. Une guitare pour savourer la musique, avec le soin artisanal présent dans chaque détail.',['Qualité sonore','Confort de jeu','Esthétique sobre']],'T-3':['La tradition en évolution.','Pour les guitaristes confirmés qui recherchent davantage de projection, une plus grande richesse harmonique et un sustain prolongé, sans renoncer au confort de jeu ni à la chaleur et à la douceur de la guitare classique espagnole.',['Confort de jeu','Projection accrue','Richesse harmonique','Sustain prolongé','Chaleur et douceur traditionnelles']],ECO:['D’autres bois. De nouvelles voix.','Une démarche née de la recherche sur des bois alternatifs. Mes racines et le savoir-faire acquis en France se rencontrent dans une exploration des matériaux, de leurs associations et de leurs possibilités sonores, dans le respect de l’environnement.',['Recherche sur les matériaux','Racines argentines','Exploration sonore']],special:['D’autres façons de faire vivre la musique.','Guitarrón argentin, guitare basse et requinto. Des instruments liés aux musiques d’Amérique latine, chacun avec son registre, sa fonction et son identité.',['Guitarrón argentin','Guitare basse','Requinto']],custom:['Un projet qui commence avec vous.','Tout commence par un échange : votre façon de jouer, le son que vous recherchez et vos préférences. Ensemble, nous définirons les possibilités de l’instrument et les détails d’un projet personnel.',['Écoute et dialogue','Recherche partagée','Détails personnels']] }},
en:{line:'Guitars by a maker',intro:'Tradition, tonal exploration and a personal relationship with every musician.',collection:'A voice, a companion.',evolution:'Constantly evolving…',photo:'Original workshop photographs. Their correspondence with each model is yet to be confirmed.',craft:'The art of listening.',craftText:'I am Victor Iermito, a classical guitar maker based in France. My work brings the Spanish guitar tradition together with an ever-evolving exploration of sound. Every conversation with a musician opens up new possibilities.',discover:'Discover',listen:'Listen',enquire:'Let’s talk about this instrument',essence:'Tradition as a starting point.<br>Sound as a horizon.',soundText:'Projection, richness and response under the fingers. An exploration renewed with every instrument.',detail:'Precision, seen up close.',real:'VICTOR IERMITO · ORIGINAL PHOTOGRAPH',models:{'T-1':['Essential simplicity.','The simplest offering in the T family. A guitar with understated aesthetics, built with the same care and craftsmanship.',['Simple aesthetics']],'T-2':['Sound and balance.','For those who value beautiful sound, playing comfort and understated aesthetics. A guitar for the pleasure of making music, with craftsmanship expressed in every detail.',['Beautiful sound','Playing comfort','Understated aesthetics']],'T-3':['Tradition in evolution.','For experienced guitarists seeking greater projection, richer harmonics and longer sustain, without sacrificing playing comfort or the warmth and sweetness of the Spanish classical guitar.',['Playing comfort','Greater projection','Rich harmonics','Extended sustain','Traditional warmth and sweetness']],ECO:['Other woods. New voices.','Born from research into alternative woods. My roots and the craft I learned in France come together in an exploration of materials, combinations and tonal possibilities, with respect for the environment.',['Material research','Argentine roots','Tonal exploration']],special:['Other ways to make music.','Argentine guitarrón, bass guitar and requinto. Instruments connected to Latin American music, each with its own range, musical role and identity.',['Argentine guitarrón','Bass guitar','Requinto']],custom:['A project that begins with you.','It begins with a conversation: your playing, the sound you seek and your preferences. Together, we will define the instrument’s possibilities and the details of a personal project.',['Listening and dialogue','Shared exploration','Personal details']] }}
};
const availabilityCopy={
 es:{label:'Disponibilidad',note:'Todos los modelos pueden realizarse por encargo. Algunos también están disponibles en el taller; consultame por los instrumentos disponibles.',order:'Fabricación por encargo',t2:'Habitualmente disponible en el taller',t3:'Disponible en el taller con menor frecuencia',other:'Disponibilidad ocasional / Por encargo'},
 fr:{label:'Disponibilité',note:'Tous les modèles peuvent être réalisés sur commande. Certains sont également disponibles à l’atelier ; contactez-moi pour connaître les instruments disponibles.',order:'Fabrication sur commande',t2:'Habituellement disponible à l’atelier',t3:'Disponible moins fréquemment à l’atelier',other:'Disponibilité occasionnelle / Sur commande'},
 en:{label:'Availability',note:'All models can be made to order. Some are also available at the workshop; please ask about the instruments currently available.',order:'Made to order',t2:'Usually available at the workshop',t3:'Available less frequently at the workshop',other:'Occasionally available / Made to order'}
};
function availability(k){const c=availabilityCopy[lang];return k==='T-2'?c.t2:k==='T-3'?c.t3:k==='special'?c.other:c.order}
function availabilityNote(){return `<p class="availability-note">${availabilityCopy[lang].note}</p>`}
function catalogueCard(k){return signatureCard(k).replace('</h2>',`</h2><p class="model-availability">${availability(k)}</p>`)}
const realPhotos={ 'T-1':'assets/real/real-front.jpg','T-2':'assets/real/session-0.jpg','T-3':'assets/real/real-top.jpg',ECO:'assets/real/real-rosette.jpg',special:'assets/real/session-2.jpg',custom:'assets/real/session-1.jpg'};
for(const l of ['es','fr','en']){extra[l].special=l==='es'?'Otros instrumentos':l==='fr'?'Autres instruments':'Other instruments';extra[l].demo=editorial[l].photo;}
const baseHome=renderHome;
function ed(){return editorial[lang]}
function photoNote(){return `<p class="image-note">${ed().photo}</p>`}
function signatureCard(k){const [tag]=ed().models[k];return `<a class="signature-card" href="#/guitars/${k}"><div class="signature-image"><img src="${realPhotos[k]}" alt="Victor Iermito — ${ed().photo}" loading="lazy"></div><div class="signature-caption"><div><span class="eyebrow">${k==='T-2'||k==='T-3'?'COLLECTION T':tr('modelIntro')}</span><h2>${modelName(k)}</h2><p>${tag}</p></div><span class="arrow">↗</span></div></a>`}
renderHome=function(){baseHome();const hero=document.querySelector('.hero-photo img');hero.src='assets/real/real-top.jpg';hero.alt='Guitarra Tradition Cedro · Victor Iermito';document.querySelector('.caption').textContent=ed().real;document.querySelector('.intro').textContent=ed().intro;document.querySelector('.hero').insertAdjacentHTML('afterend',`<section class="section signature"><div class="signature-heading"><p class="eyebrow">${ed().line}</p><h2>${tr('sound')}</h2><p class="subline">${tr('search')}</p></div><div class="signature-grid">${signatureCard('T-2')}${signatureCard('T-3')}</div>${photoNote()}</section><section class="manifesto"><p class="eyebrow">VICTOR IERMITO</p><h2>${ed().essence}</h2><p>${ed().soundText}</p><a class="button" href="#listen">▷ &nbsp; ${ed().listen}</a></section>`);document.querySelector('#guitars').hidden=true;const atelier=document.querySelector('.atelier');atelier.querySelector('h2').textContent=ed().craft;atelier.querySelector('p:not(.eyebrow)').textContent=ed().craftText;atelier.querySelector('img').src='assets/real/session-2.jpg';atelier.querySelector('img').alt='Detalle de pala · Victor Iermito';const details=document.querySelector('.detail-story');details.querySelector('h2').textContent=ed().detail;details.querySelector('.subline').remove();details.querySelectorAll('img')[0].src='assets/real/session-1.jpg';details.querySelectorAll('img')[1].src='assets/real/real-top.jpg';}
renderModels=function(){const order=['T-2','T-3','T-1','ECO','special','custom'];main.innerHTML=`<section class="models-page luxury-collection"><a class="breadcrumbs" href="#/">${tr('back')} / ${tr('models')}</a><p class="eyebrow">${ed().line}</p><div class="collection-lead"><h1>${ed().collection}</h1><p class="subline">${tr('sound')}</p>${availabilityNote()}</div><div class="signature-grid">${order.slice(0,2).map(catalogueCard).join('')}</div><div class="secondary-grid">${order.slice(2).map(catalogueCard).join('')}</div>${photoNote()}</section>`;applyLanguage();};
renderModel=function(k){if(!ed().models[k]){location.hash='/guitars';return}const [title,body,features]=ed().models[k];main.innerHTML=`<section class="detail-page luxury-detail"><a class="breadcrumbs" href="#/guitars">← ${tr('models')} / ${modelName(k)}</a><div class="detail-layout"><div class="detail-photo"><img src="${realPhotos[k]}" alt="Victor Iermito — ${ed().photo}">${photoNote()}</div><div class="detail-copy"><p class="eyebrow">${tr('modelIntro')} · VICTOR IERMITO</p><h1>${modelName(k)}</h1><h2>${title}</h2><p>${body}</p>${k==='T-3'?`<p class="model-evolution">${ed().evolution}</p>`:''}<p class="model-availability"><strong>${availabilityCopy[lang].label}:</strong> ${availability(k)}</p>${availabilityNote()}<ul class="tonal-notes">${features.map(f=>`<li>${f}</li>`).join('')}</ul><a class="custom-button" href="https://www.instagram.com/victoriermitoluthier/" target="_blank" rel="noopener">${ed().enquire} ↗</a><a class="quiet-link" href="#listen">▷ ${ed().listen}</a></div></div><div class="detail-pictures"><img src="assets/real/session-1.jpg" alt="Victor Iermito · rosace" loading="lazy"><img src="assets/real/session-2.jpg" alt="Victor Iermito · détail" loading="lazy"></div><p class="eyebrow" style="margin-top:65px">${tr('others')}</p><div class="model-list">${['T-2','T-3','T-1','ECO','special','custom'].filter(x=>x!==k).map(x=>`<a class="text-link" href="#/guitars/${x}">${modelName(x)} ↗</a>`).join('')}</div></section>`;applyLanguage();};
route();
